fn encode(message: Vec<char>) -> Vec<char> {
    message
        .into_iter()
        .map(|c| match c {
            ' ' => ' ',
            // Vowel: first map, then swap case
            'a' => swap_case('c'),
            'e' => swap_case('g'),
            'i' => swap_case('k'),
            'o' => swap_case('q'),
            'u' => swap_case('w'),
            'A' => swap_case('C'),
            'E' => swap_case('G'),
            'I' => swap_case('K'),
            'O' => swap_case('Q'),
            'U' => swap_case('W'),
            // Consonant: just swap case
            other => swap_case(other),
        })
        .collect()
}

fn swap_case(c: char) -> char {
    if c.is_ascii_lowercase() {
        c.to_ascii_uppercase()
    } else {
        c.to_ascii_lowercase()
    }
}

