        let input: Vec<char> = "Hello World".chars().collect();
        let output: Vec<char> = encode(input);
        let result: String = output.into_iter().collect();
        // H -> h (consonant)
        // e -> g, then swap to G
        // l -> L
        // l -> L
        // o -> q, then swap to Q
        // ' ' -> ' '
        // W -> w (consonant)
        // o -> q, then swap to Q
